insert into public.findings (slug, title, summary, description, site_name, location_lat, location_lng, credibility_rating, credibility_note, sort_order, reviewed_on) values
  ('tall-el-hammam', 'Tall el-Hammam and the Search for Sodom', 'A large Bronze Age city northeast of the Dead Sea, violently destroyed around 1650 BC by its excavators’ dating. Its excavator identifies it as Sodom; most scholars who look for Sodom favor other sites or doubt it can be located.', 'Tall el-Hammam lies on the plain east of the Jordan River, about 8 miles (13 km) northeast of the Dead Sea. Since 2005 a team led by Steven Collins, then of Trinity Southwest University in Albuquerque and later also of Veritas International University, has excavated it under Jordan’s Department of Antiquities. In the Middle Bronze Age it was one of the largest cities in the southern Levant, with massive fortifications. It ended in a violent destruction followed by centuries of near-abandonment.

Collins argues that it is Sodom. Genesis 13:10–12 says Lot looked out from near Bethel over “all the plain of Jordan” (the kikkar) and settled among its cities. Collins reads the kikkar as the round plain north of the Dead Sea, where Tall el-Hammam is the dominant site. Most earlier proposals put Sodom southeast of the Dead Sea, at sites such as Bab edh-Dhra. Some of the strongest objections come from other evangelical scholars, such as Bryant Wood and Eugene Merrill, who place Sodom south of the Dead Sea and centuries earlier. Many critical scholars read the Sodom story as a traditional account of the Dead Sea’s barren landscape and doubt it points to one site.

In 2021 a team of scientists that included Phillip Silvia of the excavation project published a paper in Scientific Reports arguing that a cosmic airburst destroyed the city, citing melted pottery and mudbrick, shocked quartz and scattered human remains. Genesis 19:24–28 describes fire and brimstone falling on the cities, so the claim drew wide attention. Other scientists challenged the evidence and the paper’s images. The authors corrected altered images in 2022 and a misused figure in 2023, and the journal added an editor’s note of concern in February 2023. In April 2025 Scientific Reports retracted the paper, saying it no longer had confidence in its conclusions; most of the authors disagreed with the retraction.', 'Tall el-Hammam, Jordan', 31.8403, 35.6731, 'debated', 'This rating covers the identification with Sodom. The excavation is real and extensive, and the destruction layer is well attested. The identification rests on reading Genesis 13:10–12 as placing the cities north of the Dead Sea, and it requires dating Abraham centuries later than the traditional biblical chronology. A 2021 paper attributing the destruction to a cosmic airburst was corrected twice and then retracted by its journal in 2025; most of its authors disagreed with the retraction.', 1, '2026-10-14'),
  ('exodus-route', 'Tracing the Exodus Route', 'Scholars have proposed northern, central, southern and Arabian routes for Israel’s journey from Egypt to Sinai. Egyptian sites shed light on the setting, but archaeology has confirmed no route or campsite.', 'Exodus and Numbers give a detailed itinerary: from Rameses to Succoth, then Etham and Pi-hahiroth, across the sea, and on through the wilderness to Mount Sinai and Kadesh-barnea (Exodus 12:37; 13:20; 14:2; Numbers 33). Many of these places cannot be located with confidence today.

Some of the setting can be tested. Excavations at Qantir in the eastern Nile Delta have uncovered Pi-Ramesses, the capital Ramesses II built in the 13th century BC, which many identify with the store city Raamses of Exodus 1:11. James Hoffmeier of Trinity Evangelical Divinity School excavated forts at Tell el-Borg on the “Ways of Horus,” Egypt’s military road along the coast. That road matches “the way of the land of the Philistines,” which Exodus 13:17 says Israel avoided.

Mount Sinai has been placed at Jebel Musa in southern Sinai, venerated by Christians since at least the 4th century. St. Catherine’s Monastery at its foot is a Greek Orthodox monastery still in use today; rabbinic tradition did not fix the mountain’s location. Other proposals put Sinai in northern Sinai, in the Negev (Har Karkom), or in northwest Arabia, ancient Midian, which some critical scholars such as Frank Moore Cross have favored. One Arabian candidate, Jebel al-Lawz, was made popular by independent explorers such as Ron Wyatt and Bob Cornuke; most archaeologists, including evangelical ones, reject it. Excavations at Tell el-Qudeirat, the site most often identified as Kadesh-barnea, where Numbers says Israel spent much of the wilderness period, found Iron Age fortresses but nothing earlier.

Scholars disagree on what this absence means. Some argue that a large migration would leave traces, and that their absence counts against the story as history. Others note that nomadic camps rarely survive and that the Egyptian setting fits the story well. Many critical scholars think the story grew from the memory of a smaller group, and some doubt any exodus took place; others see the itinerary as reflecting the geography of a later period.', 'Jebel Musa, southern Sinai, Egypt', 28.5392, 33.9753, 'unverified', 'This rating covers the proposed routes and the location of Mount Sinai. Egyptian archaeology sheds light on the story’s setting, such as the city of Pi-Ramesses and Egypt’s fortified road across northern Sinai. But no campsite or trail of a large group has been identified, and none of the proposed routes or locations for Mount Sinai is confirmed. Scholars disagree on whether a people living in tents would leave such traces.', 2, '2026-10-14'),
  ('red-sea-chariot-wheels', 'Red Sea “Chariot Wheels”', 'Since 1978, divers have reported coral-covered shapes resembling chariot wheels in the Gulf of Aqaba near Nuweiba. No object has been made available for study, and archaeologists, including many who accept the Exodus, do not consider the claim evidence.', 'Exodus 14 tells how Israel crossed the sea on dry ground and how the returning waters covered Pharaoh’s chariots and horsemen. Where the crossing happened is unknown. The Hebrew yam suph (“Sea of Reeds,” traditionally “Red Sea”) has been placed at lakes near the Suez isthmus, at the Gulf of Suez and at the Gulf of Aqaba. Supporters of a crossing in the Gulf of Aqaba note that 1 Kings 9:26 uses yam suph for the gulf near Elath.

In 1978 Ron Wyatt, an American nurse anesthetist with no archaeological training, began reporting chariot wheels and bones on the floor of the Gulf of Aqaba off Nuweiba, a beach on the Sinai coast. By his own account he raised an eight-spoked wheel hub and took it to Nassif Mohammed Hassan, Egypt’s director of antiquities, who dated it to the 18th Dynasty because, Wyatt said, eight-spoked wheels were used only then. No record of that examination has been produced, and the hub has never been made available for study. The premise is also mistaken: Egyptian chariot wheels of that dynasty normally had four or six spokes. Wyatt also described gold-covered wheels on the seabed, none of which has been raised. Later divers and filmmakers have published images of coral-covered shapes that look like wheels and axles.

Archaeologists, including evangelical scholars at the Associates for Biblical Research, have rejected the claim, as have writers from Wyatt’s own Seventh-day Adventist church, such as Russell and Colin Standish. No artifacts have been raised for testing, Egyptian authorities have confirmed no finds, and coral grows over many shapes, natural and man-made. The Nuweiba crossing is tied to identifying Mount Sinai with Jebel al-Lawz in Saudi Arabia, which most scholars also reject.', 'Nuweiba, Gulf of Aqaba, Egypt', 28.9706, 34.6544, 'unverified', 'This rating covers the claim that chariot remains from the Exodus lie off Nuweiba. It rests on underwater photographs and video of encrusted shapes, and on reports about objects that have never been made available for study. No excavation, laboratory analysis or peer-reviewed publication supports it. A wheel-like shape under coral is not enough to identify a chariot, its date or its origin.', 3, '2026-10-14'),
  ('ark-of-the-covenant', 'The Ark of the Covenant: What Became of It?', 'The Bible’s record of the Ark ends before the Babylonians destroyed Jerusalem in 586 BC, and no archaeological trace of it has been found. Many historians think it was lost or destroyed by then; traditions place it in Ethiopia, on Mount Nebo, in Babylon or beneath the Temple Mount.', 'Exodus 25:10–22 describes the Ark as a gold-covered wooden chest, carried on poles, that held the tablets of the covenant. The Bible follows it from the wilderness to Shiloh, into Philistine hands, to Kiriath-jearim for twenty years, and finally into Solomon’s Temple (1 Samuel 4–7; 2 Samuel 6; 1 Kings 8). Its last narrative mention is Josiah’s order, around 622 BC, to put it back in the Temple (2 Chronicles 35:3).

When the Babylonians destroyed the Temple in 586 BC, 2 Kings 25:13–17 lists the Temple furnishings they carried off, mostly bronze but also gold and silver vessels, and does not mention the Ark. Jeremiah 3:16 speaks of a day when it will no longer be remembered or made again. 1 Esdras 1:54 and 2 Esdras 10:22 suggest it was taken or plundered, and 2 Maccabees 2:4–8 says Jeremiah hid it in a cave on Mount Nebo. Rabbinic sources record two views: that King Josiah hid it beneath the Temple, and that it was carried to Babylon (Talmud, Yoma 52b–54a).

The Ethiopian Orthodox Church holds that the Ark was brought to Ethiopia and is kept at the Church of Our Lady Mary of Zion in Aksum, where only one guardian monk may see it. The tradition is told in the Kebra Nagast, which says Menelik I, son of Solomon and the Queen of Sheba, brought it there. Every Ethiopian Orthodox church keeps a consecrated tabot, representing the tablets, at its altar. Historians date the Kebra Nagast in its present form to the 14th century AD; the church holds that it preserves older tradition.

Modern claims include Ron Wyatt’s report of finding the Ark in a cave near the Garden Tomb, a site some Protestants identify as Golgotha. He produced no clear photographs or artifacts, and the Garden Tomb Association says nothing was found. Archaeology has instead examined places in the Ark’s story. A 2017 excavation at Kiriath-jearim uncovered a large monumental platform on the hilltop, which the excavators date, mainly by pottery, to the first half of the 8th century BC and attribute to the northern kingdom of Israel. Egyptian finds, such as the carrying chest of Anubis from Tutankhamun’s tomb, are similar to the object the Bible describes.', 'Temple Mount, Jerusalem', 31.7781, 35.2354, 'unverified', 'This rating covers claims to have found the Ark or to know where it is. There is no physical evidence of the Ark itself, and no modern claim to have found it has been substantiated. The Ethiopian Orthodox Church’s tradition is a matter of faith; by its practice the Ark is shown to no one, so it cannot be examined. Archaeology can show objects like the one Exodus describes and study places linked to it, but it cannot tell what became of it.', 4, '2026-10-14'),
  ('jericho-walls', 'The Walls of Jericho', 'Excavations at Tell es-Sultan have found a city destroyed by fire, with collapsed mudbrick walls. Archaeologists have argued for nearly a century over whether that destruction matches the date of Joshua’s conquest.', 'Tell es-Sultan, ancient Jericho, is one of the oldest settlements on earth, with remains reaching back before 8000 BC. Joshua 6 tells how its walls fell after Israel marched around the city for seven days, and how the city was burned (6:20, 24).

John Garstang excavated the mound from 1930 to 1936. He reported a fallen double wall and a burned city that he dated to around 1400 BC, and took them as confirmation of Joshua. Kathleen Kenyon dug from 1952 to 1958 with more refined methods. She concluded that Garstang’s walls were about a thousand years older, and that the last walled city (City IV) was destroyed around 1550 BC, with only slight occupation afterward.

In 1990 Bryant Wood of the Associates for Biblical Research re-examined the pottery and argued for a destruction around 1400 BC after all. He pointed to collapsed mudbrick at the foot of the city’s revetment wall, a destructive fire, and storage jars full of grain, which suggest a short siege soon after harvest, as Joshua 2:6 and 3:15 imply. Radiocarbon measurements on charred grain from the destruction, published by Hendrik Bruins and Johannes van der Plicht in 1995 and calibrated by them in 1996, point to the 16th century BC, supporting Kenyon; Wood has disputed how those results should be read. An Italian–Palestinian expedition, working since 1997, dates the destruction to about 1550–1525 BC and reports traces of a smaller Late Bronze Age settlement afterward.

Scholars who favor a 15th-century Exodus read the destruction as Joshua’s. Some who favor a 13th-century date, such as Kenneth Kitchen, argue that erosion removed most of the later city. Many critical scholars see Joshua 6 as a later theological account rather than a battle report, and see Israel as emerging largely from within Canaan. Tell es-Sultan was inscribed as a UNESCO World Heritage Site in 2023.', 'Tell es-Sultan, Jericho', 31.8711, 35.444, 'debated', 'This rating covers whether the destruction matches Joshua’s conquest. The excavations are well documented; the disagreement is over dating. John Garstang, and later Bryant Wood, dated the destroyed city (City IV) to about 1400 BC, close to the conquest date implied by 1 Kings 6:1. Kathleen Kenyon’s pottery analysis and later radiocarbon tests dated it to about 1550 BC, leaving little or no walled city for Joshua. Most archaeologists accept the earlier date, including the current Italian–Palestinian expedition; Wood’s date is held mainly by scholars who favor a 15th-century Exodus.', 5, '2026-10-14'),
  ('mesha-stele', 'The Mesha Stele (Moabite Stone)', 'A basalt monument in which Mesha, king of Moab, boasts of throwing off Israel’s rule around 840 BC. It names Omri king of Israel and Israel’s God, YHWH, and tells the revolt mentioned in 2 Kings 1:1 and 3:5 from Moab’s side.', 'In 1868 F. A. Klein, an Anglican missionary, was shown a black basalt slab bearing 34 lines of writing at Dhiban, east of the Dead Sea. While European agents competed to acquire it, local people heated the stone and broke it apart with cold water in 1869. A squeeze (paper impression) made for Charles Clermont-Ganneau before the breakage, together with recovered fragments preserving about 600 of its roughly 1,000 letters, allowed the text to be reconstructed. The restored stele is in the Louvre.

Mesha says that “Omri was king of Israel and oppressed Moab many days,” and that his son continued to do so, until Mesha rebelled with the help of his god Chemosh. He describes taking Israelite towns such as Nebo and Ataroth, and dragging the vessels of YHWH before Chemosh (the word “vessels” is partly restored). It is the earliest undisputed mention of Israel’s God by name outside the Bible.

2 Kings 1:1 and 3:4–27 tell of the same rebellion. Mesha, a sheep-breeder who paid Israel a heavy tribute, revolted after Ahab’s death, and Israel, Judah and Edom marched against him. The Bible says the coalition was winning until Mesha sacrificed his eldest son on the wall, and “there was great indignation against Israel,” so they withdrew. Mesha’s stone records only his victories. It also seems to place the revolt in the reign of Omri’s son, while 2 Kings places it after Ahab’s death; scholars explain this in different ways, and “son” can also mean a later descendant. Read together, the two accounts show Moab’s revolt from both sides.', 'Dhiban (biblical Dibon), Jordan', 31.5003, 35.7767, 'established', 'This rating covers the stele as Mesha’s own record of Moab’s revolt against Israel. Europeans saw the stone intact in place, and a paper squeeze was taken before it was broken, so most of its text is securely known; it is one of the most studied inscriptions of the Iron Age. It names Mesha, Omri and Israel’s rule over Moab, as 2 Kings 1:1 and 3:4–5 do, though the two accounts describe different stages of the conflict and differ on its timing. A proposed reading of “House of David” in line 31 is possible but debated, because the letters there are damaged.', 6, '2026-10-14'),
  ('tel-dan-stele', 'The Tel Dan Stele: “House of David”', 'Pieces of a 9th-century BC Aramaic victory monument, found at Tel Dan in 1993 and 1994. Its phrase “House of David” is the earliest widely accepted reference to David outside the Bible.', 'In July 1993 a team led by Avraham Biran was excavating near the city gate at Tel Dan when it found a broken basalt slab reused in a later wall. Two more fragments turned up in 1994. The text is in Aramaic. Most scholars think Hazael, king of Aram-Damascus, set it up in the second half of the 9th century BC to celebrate victories over his neighbors.

The writer boasts that he killed “[Jo]ram son of [Ahab], king of Israel” and “[Ahaz]iah son of [Jehoram], king of the House of David.” The names are partly restored, but the restoration is widely accepted, because the surviving letters and the context fit those two kings, who reigned at the same time.

The stele bears on 2 Kings 8–9 in two ways. It shows that Israel and Judah were kingdoms known to their neighbors, with Judah’s royal line named after David. It also differs from the Bible. 2 Kings 9 says Jehu killed Joram and Ahaziah, while the stele gives the credit to the Aramean king. Some scholars suggest Jehu acted as Hazael’s ally, or that each side claimed the same event. The Bible itself says Hazael had just fought Joram at Ramoth-gilead (2 Kings 8:28–29).

The fragments are displayed at the Israel Museum in Jerusalem.', 'Tel Dan, northern Israel', 33.2486, 35.6525, 'established', 'This rating covers the stele and its reading “House of David.” The fragments come from a controlled excavation and were published in a peer-reviewed journal; their authenticity is not seriously disputed. Most scholars read bytdwd as “House of David,” a dynasty name like “House of Omri,” and early alternative readings have found little support. The stele shows that a dynasty claiming David as its founder ruled Judah by the 9th century BC; it says nothing about the details of David’s own life.', 7, '2026-10-14'),
  ('siege-of-lachish', 'The Assyrian Siege of Lachish', 'Sennacherib’s 701 BC campaign against Judah is recorded in his own annals, carved in palace reliefs of the siege of Lachish, and visible in the siege ramp still at the site. The Bible tells of the same campaign in 2 Kings 18–19, Isaiah 36–37 and 2 Chronicles 32.', 'In 701 BC Sennacherib of Assyria marched on Judah after King Hezekiah rebelled. His annals survive on clay prisms such as the Taylor Prism in the British Museum. They claim he took 46 walled cities and shut Hezekiah up in Jerusalem “like a bird in a cage.” They do not claim Jerusalem fell. They record Hezekiah’s tribute, including 30 talents of gold, the same figure given in 2 Kings 18:14. The annals do not name Lachish; the reliefs do.

Lachish, Judah’s second city, is the centerpiece of a series of wall reliefs from Sennacherib’s palace at Nineveh, excavated by Austen Henry Layard in the 1840s and now in the British Museum. They show battering rams on a ramp, defenders on the walls, captives led away, and Sennacherib on his throne receiving the spoil of Lachish. 2 Kings 18:14, 17 and 19:8 place Sennacherib at Lachish.

Excavations at Tel Lachish, begun by James Starkey in the 1930s and above all those led by David Ussishkin from 1973 to 1987, exposed the Assyrian siege ramp, one of the earliest siege ramps known, along with a counter-ramp built by the defenders, arrowheads, sling stones and a thick destruction layer. Storage-jar handles stamped lmlk (“belonging to the king”), linked with Hezekiah’s preparations, were found in that layer.

The sources part ways at the end of the campaign. 2 Kings 19:35–36 says the angel of the LORD struck the Assyrian camp and Sennacherib returned home, while his annals report only success and tribute. Historians debate what happened, but all the sources agree Jerusalem was not taken.', 'Tel Lachish, Israel', 31.565, 34.849, 'established', 'This rating covers Sennacherib’s campaign against Judah in 701 BC. Three kinds of evidence agree: Assyrian texts, Assyrian palace art and excavation at Lachish. They show that Sennacherib invaded Judah, took Lachish, and besieged Jerusalem without capturing it, as the Bible reports. Both the annals and 2 Kings record Hezekiah’s tribute, with the same 30 talents of gold, though they differ on the silver (800 talents in the annals, 300 in 2 Kings 18:14). They also differ on how the campaign ended: Sennacherib reports only success, while 2 Kings 19 reports a disaster for his army.', 8, '2026-10-14'),
  ('hezekiahs-tunnel', 'Hezekiah’s Tunnel and the Siloam Inscription', 'A 533-meter tunnel cut through bedrock to bring the Gihon Spring’s water inside Jerusalem, with a Hebrew inscription describing the moment the two digging crews met. Most scholars identify it with the work in 2 Kings 20:20, where Hezekiah “made a pool, and a conduit, and brought water into the city.”', 'The Gihon Spring, Jerusalem’s main water source, rises in the Kidron Valley below the eastern side of the City of David. Hezekiah’s Tunnel carries its water through the hill to the Pool of Siloam on the other side. It winds for about 533 meters, with a drop of only about 30 centimeters along its length.

In 1880 a boy wading in the tunnel noticed an inscription near its southern end. Written in paleo-Hebrew script, it describes the last moments of the work. Two crews, digging toward each other with picks, heard each other’s voices through the rock and broke through “axe against axe,” and the water flowed 1,200 cubits to the pool. In 1890 the inscription was cut out of the wall, breaking into several pieces; Ottoman authorities recovered it and sent it to Istanbul, where it is in the Istanbul Archaeology Museums.

2 Kings 20:20 and 2 Chronicles 32:2–4, 30 say Hezekiah stopped the springs outside the city and brought the Gihon’s water down to the west side of the City of David, as Jerusalem prepared for the Assyrian invasion of 701 BC. A 2003 study in Nature radiocarbon-dated plant material in the tunnel’s original plaster to around 700 BC; uranium–thorium dates from stalactites that grew in the tunnel afterward gave a consistent minimum age.', 'City of David (Silwan), Jerusalem', 31.7726, 35.2358, 'established', 'This rating covers the tunnel and its attribution to Hezekiah. The tunnel can be walked today and the inscription is in a museum; neither is in doubt. Radiocarbon dating of plant material in the tunnel’s plaster, published in 2003, points to about 700 BC, fitting Hezekiah’s reign, and most scholars accept the attribution. A minority have argued for an earlier or a later date, and the inscription itself names no king.', 9, '2026-10-14'),
  ('cyrus-cylinder', 'The Cyrus Cylinder', 'A clay cylinder in which Cyrus the Great of Persia describes conquering Babylon in 539 BC and returning displaced peoples and their gods to their homelands. Many historians see it as reflecting the kind of policy behind the decree in Ezra 1, though it does not mention the Jews.', 'Hormuzd Rassam found the cylinder at Babylon in 1879, digging for the British Museum; his own accounts of the exact findspot differ. It was made as a foundation deposit, and its text describes Cyrus’s work on Babylon’s city wall. Written in Babylonian cuneiform, it presents Cyrus as chosen by Marduk to replace the impious Nabonidus, and as entering Babylon peacefully in 539 BC.

Cyrus says he returned the gods of several cities to their shrines and “gathered all their people and returned them to their settlements.” Ezra 1:1–4 and 2 Chronicles 36:22–23 report a proclamation in Cyrus’s first year allowing the Jews to return to Jerusalem and rebuild the house of the LORD. Ezra 6:2–5 says a record of the decree was later found at Ecbatana, and quotes it.

Isaiah 44:28 and 45:1 call Cyrus the LORD’s “shepherd” and “anointed.” Traditional Jewish and Christian readers take this as prophecy by the 8th-century Isaiah; most critical scholars date Isaiah 40–55 to the time of Cyrus. Many historians see the return of the exiles as fitting Cyrus’s practice of restoring local cults. Others, such as Amélie Kuhrt, caution that the cylinder is standard Babylonian royal propaganda and does not prove an empire-wide policy. The cylinder is in the British Museum.', 'Babylon, Iraq', 32.5364, 44.4209, 'established', 'This rating covers the cylinder as Cyrus’s own account of taking Babylon and restoring sanctuaries. It is a genuine, well-understood royal text from British Museum excavations at Babylon, though its exact findspot was poorly recorded. Its connection to Ezra is indirect: it names only cities and gods in Mesopotamia and western Iran, not Judah or the Jews. Many historians see it as consistent with the tradition of a Cyrus edict in Ezra 1 and 6; others, such as Amélie Kuhrt, argue it reflects Babylonian royal convention rather than a general Persian policy. Scholars also debate how closely Ezra 1:2–4 preserves Cyrus’s words; the Aramaic record in Ezra 6:3–5 is more often accepted as authentic in substance.', 10, '2026-10-14'),
  ('caiaphas-ossuary', 'The Caiaphas Ossuary', 'An ornate bone box found in a Jerusalem tomb in 1990, inscribed “Joseph son of Caiaphas.” Many scholars think it held the bones of the high priest who handed Jesus over to Pilate.', 'In November 1990, construction work in Jerusalem’s Peace Forest broke into the roof of a 1st-century burial cave. Zvi Greenhut of the Israel Antiquities Authority found about a dozen ossuaries, limestone boxes in which bones were gathered about a year after burial. The most elaborate, carved with rosettes, is inscribed “Yehosef bar Qayafa,” Joseph son of Caiaphas, and held the bones of six people, including a man of about sixty.

The Gospels name Caiaphas as the high priest when Jesus was arrested and questioned (Matthew 26:57; John 11:49–53; 18:13–14, 24). Josephus gives his full name as Joseph Caiaphas, high priest from about AD 18 to 36. A decorated ossuary bearing that name, in a family tomb of the right period, fits him well.

The bones were reburied, and the ossuary is displayed in the Israel Museum in Jerusalem.', 'Peace Forest, Jerusalem', 31.7598, 35.2288, 'supported', 'This rating covers the identification of the ossuary’s Joseph son of Caiaphas with the high priest. The tomb and the ossuary come from a documented salvage excavation and are not in doubt. That this Joseph son of Caiaphas is the high priest is probable rather than certain. The name matches Josephus’s “Joseph who was called Caiaphas,” and the box is richly decorated, but the inscription gives no title, and a few scholars question the reading of the family name.', 11, '2026-10-14'),
  ('pilate-stone', 'The Pilate Stone', 'A limestone block found at Caesarea in 1961 that bears the name of Pontius Pilate and his title, prefect of Judea. It is the only known inscription from his lifetime that clearly names him.', 'In 1961 an Italian expedition led by Antonio Frova was excavating the Roman theater at Caesarea Maritima, the seat of Roman government in Judea. A limestone block, reused as a step in a later rebuilding, carried part of a Latin dedication. Its lines read, in part, “Tiberieum … [Po]ntius Pilatus … [Praef]ectus Iuda[ea]e”: Pontius Pilate, prefect of Judea, had dedicated a building called a Tiberieum, in honor of the emperor Tiberius.

All four Gospels name Pilate as the governor who sentenced Jesus, and Luke 3:1 dates John the Baptist’s ministry to the time when “Pontius Pilate being governor of Judaea.” Josephus and Philo also write about him. The stone settles the title of his office. Before Claudius, Rome’s governors of Judea were prefects (praefectus), a military title, not procurators, as the later historian Tacitus called him.

The original is in the Israel Museum in Jerusalem; a replica stands at Caesarea.', 'Caesarea Maritima, Israel', 32.4979, 34.8909, 'established', 'This rating covers the inscription and its naming of Pilate as prefect of Judea. Found in a documented excavation and displayed in the Israel Museum, the inscription is universally accepted. It confirms Pilate as a real Roman official in Judea who held the title praefectus, consistent with the Gospels, Josephus and Philo. Debate centers on details, such as what the building called the Tiberieum was.', 12, '2026-10-14'),
  ('pool-of-siloam', 'The Pool of Siloam', 'A large stepped pool from the time of Jesus, uncovered by accident in Jerusalem in 2004. Most scholars identify it as the pool of Siloam, where John’s Gospel says Jesus sent a blind man to wash.', 'In 2004 workers repairing a sewer pipe south of the Old City exposed stone steps. Archaeologists Ronny Reich and Eli Shukron found that the steps belonged to a large pool, more than 50 meters long, with flights of steps separated by landings. Coins in the plaster and fill date its use to the 1st centuries BC and AD, ending around the Roman destruction of Jerusalem in AD 70.

John 9 tells how Jesus put clay on a blind man’s eyes and told him, “Go, wash in the pool of Siloam,” and the man came back seeing. The small pool shown to visitors for centuries dates from Byzantine times. The discovery shows a large public pool at the place the Gospel implies, which the excavators think pilgrims used for ritual washing before going up to the Temple. Along with the Pool of Bethesda (John 5:2), it has led many scholars to give more weight to the Gospel of John’s knowledge of Jerusalem.

In December 2022 Israeli authorities announced that the rest of the pool would be excavated, and work began in 2023. Nahshon Szanton, who directed that work, has argued that this large pool is the one Josephus calls Solomon’s Pool, used for bathing, and that the Siloam of John 9 was the smaller pool at the tunnel’s outlet, as Yoel Elitzur had also proposed. Both lay in the same water system at the foot of the City of David.', 'City of David (Silwan), Jerusalem', 31.7706, 35.2351, 'supported', 'This rating covers the identification of the 2004 pool with the pool of Siloam in John 9. Ronny Reich of the University of Haifa and Eli Shukron of the Israel Antiquities Authority excavated it and dated it by coins and pottery to the late Second Temple period, and most scholars accept the identification because it lies at the outlet of the Siloam water system. Some disagree: Nahshon Szanton of the Israel Antiquities Authority, who directed the 2023 excavation, argues that it is the pool Josephus calls Solomon’s Pool, and that John’s Siloam was the smaller pool beside it. Either way, a pool of Siloam stood where the Gospel places it.', 13, '2026-10-14')
on conflict (slug) do update set title = excluded.title, summary = excluded.summary,
  description = excluded.description, site_name = excluded.site_name,
  location_lat = excluded.location_lat, location_lng = excluded.location_lng,
  credibility_rating = excluded.credibility_rating, credibility_note = excluded.credibility_note,
  sort_order = excluded.sort_order, reviewed_on = excluded.reviewed_on, updated_at = now();

delete from public.findings where slug not in ('tall-el-hammam', 'exodus-route', 'red-sea-chariot-wheels', 'ark-of-the-covenant', 'jericho-walls', 'mesha-stele', 'tel-dan-stele', 'siege-of-lachish', 'hezekiahs-tunnel', 'cyrus-cylinder', 'caiaphas-ossuary', 'pilate-stone', 'pool-of-siloam');

