insert into public.finding_timeline (finding_id, position, year, label, event)
select f.id, v.position, v.year, v.label, v.event
from (values
  ('tall-el-hammam', 1, -1650, 'c. 1650 BC', 'The Middle Bronze Age city is destroyed (the excavators’ date).'),
  ('tall-el-hammam', 2, 2005, '2005', 'Excavation begins under Steven Collins.'),
  ('tall-el-hammam', 3, 2013, '2013', 'Collins and Latayne Scott publish Discovering the City of Sodom.'),
  ('tall-el-hammam', 4, 2021, '2021', 'The airburst paper is published in Scientific Reports.'),
  ('tall-el-hammam', 5, 2025, '2025', 'Scientific Reports retracts the airburst paper; most of its authors object.'),
  ('exodus-route', 1, -1446, 'c. 1446 BC', 'A proposed early date for the Exodus, from 1 Kings 6:1.'),
  ('exodus-route', 2, -1250, 'c. 1250 BC', 'A proposed later date for the Exodus, in the reign of Ramesses II (Exodus 1:11).'),
  ('exodus-route', 3, 330, '4th century AD', 'Christian monks venerate Jebel Musa as Mount Sinai.'),
  ('exodus-route', 4, 565, 'c. AD 565', 'St. Catherine’s Monastery is completed under Emperor Justinian.'),
  ('exodus-route', 5, 1976, '1976–1982', 'Rudolph Cohen excavates Tell el-Qudeirat (Kadesh-barnea).'),
  ('exodus-route', 6, 1999, '1999–2008', 'James Hoffmeier excavates Tell el-Borg in northern Sinai.'),
  ('red-sea-chariot-wheels', 1, 1978, '1978', 'Ron Wyatt reports chariot wheels off Nuweiba.'),
  ('red-sea-chariot-wheels', 2, 1999, '1999', 'Ron Wyatt dies.'),
  ('red-sea-chariot-wheels', 3, 2002, '2002', 'Lennart Möller’s The Exodus Case promotes the Nuweiba crossing.'),
  ('ark-of-the-covenant', 1, -960, 'c. 960 BC', 'Solomon brings the Ark into the Temple (1 Kings 8).'),
  ('ark-of-the-covenant', 2, -622, 'c. 622 BC', 'Josiah orders the Ark returned to the Temple (2 Chronicles 35:3).'),
  ('ark-of-the-covenant', 3, -586, '586 BC', 'The Babylonians destroy the Temple; the Ark is not listed among the spoils (2 Kings 25).'),
  ('ark-of-the-covenant', 4, 2017, '2017', 'Excavation at Kiriath-jearim, where 1 Samuel 7:2 says the Ark rested for twenty years.'),
  ('jericho-walls', 1, -1550, 'c. 1550 BC', 'City IV is destroyed, by Kenyon’s dating and the radiocarbon results.'),
  ('jericho-walls', 2, -1400, 'c. 1400 BC', 'City IV is destroyed, by Garstang’s and Wood’s dating, which links it to Joshua 6.'),
  ('jericho-walls', 3, 1930, '1930–1936', 'John Garstang excavates.'),
